partial class Canvas {
 // Latch modifiers during the gesture, including a key pressed after mouse-down.
 // Releasing the modifier just before the mouse must not discard the fitting request.
 void UpdateFreehandModifiers(Keys keys){if(freehandPoints!=null)freehandModifiers|=keys&(Keys.Alt|Keys.Control|Keys.Shift);}
 static bool FitVectorArc(VectorShape shape,List<PointF> raw,int spacing){var fit=ArcAssist.Fit(raw);if(fit==null)return false;var a=fit[0];var b=fit[fit.Count/2];var c=fit.Last();double bx=b.X-a.X,by=b.Y-a.Y,cx=c.X-a.X,cy=c.Y-a.Y,det=2*(bx*cy-by*cx);if(Math.Abs(det)<.00001)return false;double b2=bx*bx+by*by,c2=cx*cx+cy*cy,ox=(cy*b2-by*c2)/det+a.X,oy=(bx*c2-cx*b2)/det+a.Y,r=Math.Sqrt((a.X-ox)*(a.X-ox)+(a.Y-oy)*(a.Y-oy)),start=Math.Atan2(a.Y-oy,a.X-ox),previous=start,sweep=0;foreach(var p in fit.Skip(1)){double angle=Math.Atan2(p.Y-oy,p.X-ox),delta=angle-previous;while(delta>Math.PI)delta-=2*Math.PI;while(delta< -Math.PI)delta+=2*Math.PI;sweep+=delta;previous=angle;}
 // Quarter-circle or smaller Bezier spans retain the fitted geometry at every spacing.
 int segments=Math.Max((int)Math.Ceiling(Math.Abs(sweep)/(Math.PI/2)),(int)Math.Ceiling(100.0/Math.Max(10,Math.Min(50,spacing))));double step=sweep/segments,handle=4.0/3*Math.Tan(step/4)*r;shape.Kind="Curvature pen";shape.Points.Clear();shape.Handles.Clear();for(int i=0;i<=segments;i++){double angle=start+step*i;shape.Points.Add(new PointF((float)(ox+r*Math.Cos(angle)),(float)(oy+r*Math.Sin(angle))));var tangent=new PointF((float)(-Math.Sin(angle)*handle),(float)(Math.Cos(angle)*handle));shape.Handles[i]=new[]{new PointF(-tangent.X,-tangent.Y),tangent};}shape.Points[0]=raw[0];shape.Points[segments]=raw.Last();return true;}
 public void TestPencilMouseGesture(List<PointF> points,Keys initial,Keys during){var first=Point.Round(ScreenPoint(points[0]));OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,first.X,first.Y,0));UpdateFreehandModifiers(initial);for(int i=1;i<points.Count;i++){if(i==points.Count/2)OnKeyDown(new KeyEventArgs(during));var p=Point.Round(ScreenPoint(points[i]));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,p.X,p.Y,0));}OnKeyUp(new KeyEventArgs(during));var end=Point.Round(ScreenPoint(points.Last()));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,end.X,end.Y,0));}
}
partial class Studio {
 protected override void WndProc(ref Message message){if(message.Msg==0x112&&(message.WParam.ToInt64()&0xfff0)==0xf100&&message.LParam==IntPtr.Zero&&canvas!=null&&canvas.Focused&&canvas.Doc!=null&&canvas.Doc.Selected.IsVector&&canvas.VectorMode=="Freehand"){message.Result=IntPtr.Zero;return;}base.WndProc(ref message);}
 public void TestVersion38(){SetDocument(new Document("A4",100),null);SelectTool("Pencil");int sizeAt=toolPanel.Controls.GetChildIndex(sizeSlider),hardnessAt=toolPanel.Controls.GetChildIndex(hardnessSlider),opacityAt=toolPanel.Controls.GetChildIndex(opacitySlider),flowAt=toolPanel.Controls.GetChildIndex(flowSlider);if(!(sizeAt<hardnessAt&&hardnessAt<opacityAt&&opacityAt<flowAt))throw new Exception("Pixel control order");using(var popup=new BrushPopup(8,100,80,90))if(!(popup.HardnessSlider.Top<popup.OpacitySlider.Top&&popup.OpacitySlider.Top<popup.FlowSlider.Top))throw new Exception("Popup control order");AddTypedLayer(true);if(vectorControls.OfType<Label>().Any(l=>l.Text.StartsWith("Freehand: draw a curve")))throw new Exception("Vector guidance removed");canvas.Focus();var message=new Message();ProcessCmdKey(ref message,Keys.P);if(canvas.VectorMode!="Freehand")throw new Exception("Vector pencil shortcut");canvas.Zoom=1;canvas.Offset=PointF.Empty;canvas.VectorWidth=4;canvas.VectorOpacity=.75f;canvas.Ink=Color.Teal;
 foreach(int spacing in new[]{10,50})foreach(bool reverse in new[]{false,true}){canvas.FreehandSpacing=spacing;var points=new List<PointF>();for(int i=0;i<=90;i++){double angle=Math.PI*i/90;points.Add(new PointF(300+(float)Math.Cos(angle)*100,230+(float)Math.Sin(angle)*100));}if(reverse)points.Reverse();int count=canvas.Doc.Selected.Vectors.Count,history=undo.Count;canvas.TestPencilMouseGesture(points,Keys.None,Keys.Alt);var path=canvas.Doc.Selected.Vectors.Last();if(path.Handles.Count==0||path.Colour!=Color.Teal||path.Width!=4||path.Opacity!=.75f||undo.Count!=history+1)throw new Exception("Alt arc modifier/style/undo");using(var geometry=path.Path()){geometry.Flatten(null,.1f);foreach(var p in geometry.PathPoints)if(Math.Abs(StrokeSession.Distance(p,new PointF(300,230))-100)>1)throw new Exception("Arc must remain circular at sparse spacing");}Travel(undo,redo);if(canvas.Doc.Selected.Vectors.Count!=count)throw new Exception("Arc undo");Travel(redo,undo);vectorMode.SelectedItem="Freehand";}
 foreach(bool late in new[]{false,true}){var points=EllipseSamples(100,70,.5,true).Take(150).ToList();canvas.TestPencilMouseGesture(points,late?Keys.None:Keys.Control,late?Keys.Control:Keys.None);var shape=canvas.Doc.Selected.Vectors.Last();if(shape.Kind!="Ellipse"||shape.Points.Count!=3)throw new Exception("Ctrl ellipse, incomplete loop and mid-stroke modifier");}
 var straight=new List<PointF>{new PointF(100,100),new PointF(150,103),new PointF(200,101),new PointF(250,100)};canvas.TestPencilMouseGesture(straight,Keys.Shift,Keys.Control);if(canvas.Doc.Selected.Vectors.Last().Kind!="Line")throw new Exception("Shift precedence");canvas.FreehandSpacing=10;dirty=false;}
}
